import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.BM5YPQmL.js";const c=JSON.parse('{"title":"درس المطاعم والضيافة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/tutorials/food.md","filePath":"ar/guide/tutorials/food.md"}'),l={name:"ar/guide/tutorials/food.md"};function o(n,s,h,d,r,p){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="درس-المطاعم-والضيافة" tabindex="-1">درس المطاعم والضيافة <a class="header-anchor" href="#درس-المطاعم-والضيافة" aria-label="Permalink to &quot;درس المطاعم والضيافة&quot;">​</a></h1><p>في هذا الدرس تصنع فيديو موضوعه: طريقة تحضير طبق مميز في أربع خطوات لمطعم خيالي. ستستخدم الحزمة <code>food</code> وثيمها <code>bistro</code>، ويستغرق العمل نحو عشر دقائق قبل التسجيل.</p><h2 id="_1-أنشئ-الحلقة" tabindex="-1">1. أنشئ الحلقة <a class="header-anchor" href="#_1-أنشئ-الحلقة" aria-label="Permalink to &quot;1. أنشئ الحلقة&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dish-steps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> food</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dish-in-steps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ar</span></span></code></pre></div><p>استخدم <code>--lang en</code> لنسخة إنجليزية. وتضم الحزمة أيضاً القالبين <code>order-to-table</code> و<code>weekly-menu</code>. يعرض <a href="./../../reference/packs.html#food">فهرس الحزم</a> كل القوالب وحقولها.</p><h2 id="_2-أدخل-بياناتك" tabindex="-1">2. أدخل بياناتك <a class="header-anchor" href="#_2-أدخل-بياناتك" aria-label="Permalink to &quot;2. أدخل بياناتك&quot;">​</a></h2><p>افتح الحلقة بالأمر <code>reelforge edit dish-steps</code> واستبدل الأسماء والأرقام والكلمة المفتاحية الافتراضية ببياناتك، أو ابدأ من لوحة التحكم (<strong>+ New episode</strong> ثم <strong>Start from template</strong>)، فيطلب النموذج كل حقل على حدة. التزم بحدود الطول الظاهرة لكل حقل.</p><p><strong>الجمهور والنبرة.</strong> رواد المطاعم ومحبو الطبخ وعملاء التوصيل. كن دافئاً وحيوياً وسريعاً، واللهجة المحلية مناسبة هنا.</p><ul><li>اعرض تحضير الطبق في أربع خطوات بمكوّن <code>steps</code> مع <code>icon</code> للحرارة أو الوقت.</li><li>اذكر السعر وساعات العمل مرة واحدة واعرضهما كعناصر <code>chip</code>.</li><li>استخدم صور أطباقك الخاصة من مجلد <code>assets/</code>.</li></ul><h2 id="_3-راجع-المحتوى" tabindex="-1">3. راجع المحتوى <a class="header-anchor" href="#_3-راجع-المحتوى" aria-label="Permalink to &quot;3. راجع المحتوى&quot;">​</a></h2><ul><li>لا ادعاءات صحية أو غذائية مثل «صحي» كوعد أو «يحرق الدهون».</li><li>عند ذكر المكونات أضف «اسأل الموظفين عن مسببات الحساسية»، ولا تدّعِ خلو الطبق منها إلا إذا أكد العميل ذلك.</li><li>أسماء مطاعم خيالية فقط؛ لا سلاسل ولا منصات توصيل حقيقية.</li></ul><h2 id="_4-تحقق-وسجّل-وصدّر" tabindex="-1">4. تحقق وسجّل وصدّر <a class="header-anchor" href="#_4-تحقق-وسجّل-وصدّر" aria-label="Permalink to &quot;4. تحقق وسجّل وصدّر&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dish-steps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dish-steps</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # after you save voice.wav in the episode folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dish-steps</span></span></code></pre></div><p>يوجد مثال مكتمل في <code>packs/food/examples/shakshuka-ar</code>؛ صدّره مع الخيار <code>--silent</code> للمقارنة.</p>`,14)])])}const g=a(l,[["render",o]]);export{c as __pageData,g as default};
